let img;

const SOURCE_IMAGE = "data:image/jpeg;base64,";

const cols = 130;

const MIN_DOT = 9;
const MAX_DOT = 9;
const SIZE_POWER = 1.5;

const MOVE_DISTANCE = 3;
const MOVE_SPEED = 0.1;
const MOVE_VARIATION = 0.04;

const TONE_COUNT = 5;

let baseHue;
let accentHue;
let dots = [];
let direction = -1;

function preload() {
  img = loadImage(SOURCE_IMAGE);
}

function setup() {
  const aspectRatio = img.height / img.width;

  const canvasWidth = 800;
  const canvasHeight = canvasWidth * aspectRatio;

  const canvas = createCanvas(canvasWidth, canvasHeight);
  canvas.parent("canvas-wrap");

  pixelDensity(1);
  colorMode(HSL, 360, 100, 100);
  noStroke();

  randomizeColors();

  const rows = round(cols * aspectRatio);

  img.resize(cols, rows);
  img.loadPixels();

  createDots(rows);

  document
    .getElementById("change")
    .addEventListener("click", changeColors);
}

function randomizeColors() {
  baseHue = random(360);
  accentHue = (baseHue + random(150, 210)) % 360;
}

function applyColor(dot) {
  if (dot.tone === 4) {
    dot.hue = baseHue;
    dot.saturation = 15;
    dot.lightness = 99;
  }

  else if (dot.tone === 2) {
    dot.hue = accentHue;
    dot.saturation = 100;
    dot.lightness = 60;
  }

  else {
    dot.hue = baseHue;
    dot.saturation = map(dot.tone, 0, 3, 100, 88);
    dot.lightness = map(dot.tone, 0, 3, 32, 68);
  }
}

function changeColors() {
  randomizeColors();

  for (const dot of dots) {
    applyColor(dot);
  }
}

function createDots(rows) {
  const cellW = width / cols;
  const cellH = height / rows;

  dots = [];

  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const index = (x + y * cols) * 4;

      const r = img.pixels[index];
      const g = img.pixels[index + 1];
      const b = img.pixels[index + 2];

      const brightnessValue = (r + g + b) / 3;
      const normalized = brightnessValue / 255;

      let tone = floor(normalized * TONE_COUNT);
      tone = constrain(tone, 0, TONE_COUNT - 1);

      const darkness = 1 - normalized;
      const sizeFactor = pow(darkness, SIZE_POWER);

      const size = lerp(
        MIN_DOT,
        MAX_DOT,
        sizeFactor
      );

      const dot = {
        x: x * cellW + cellW / 2,
        y: y * cellH + cellH / 2,

        size,
        tone,

        hue: 0,
        saturation: 0,
        lightness: 0,

        speed:
          MOVE_SPEED +
          random(
            -MOVE_VARIATION,
            MOVE_VARIATION
          ),

        offset:
          random(
            -MOVE_DISTANCE,
            0
          )
      };

      applyColor(dot);
      dots.push(dot);
    }
  }
}

function draw() {
  background(0, 0, 100);

  for (const dot of dots) {
    dot.offset +=
      dot.speed *
      direction;

    if (
      direction === -1 &&
      dot.offset < -MOVE_DISTANCE
    ) {
      dot.offset = 0;
    }

    if (
      direction === 1 &&
      dot.offset > MOVE_DISTANCE
    ) {
      dot.offset = 0;
    }

    fill(
      dot.hue,
      dot.saturation,
      dot.lightness
    );

    circle(
      dot.x + dot.offset,
      dot.y,
      dot.size
    );
  }
}
